 2	    requires arr.Length > 0
 3	    ensures pos == -1 || (0 <= pos < arr.Length && arr[pos] == elem && (pos <= arr.Length - 1 || arr[pos + 1] > elem))
 4	    ensures forall i :: 0 <= i < arr.Length ==> arr[i] == old(arr[i])
 5	{
 6	    pos := -1;
 7	    for i := 0 to arr.Length - 1
 8	        invariant 0 <= i <= arr.Length
 9	        invariant pos == -1 || (0 <= pos < i && arr[pos] == elem && (pos == i - 1 || arr[pos + 1] > elem))
10	        invariant forall k :: 0 <= k < arr.Length ==> arr[k] == old(arr[k])
11	    {
12	        if arr[i] == elem
13	        {
14	            pos := i;
15	        }
16	    }
17	}

